import{_ as a}from"./chunks/Audio.COine8Wh.js";import{c as t,o as n,j as i,G as r,ae as o,a as s}from"./chunks/framework.Bw0Gm4PQ.js";const f=JSON.parse('{"title":"IMPROVING THE SAFETY AND SECURITY OF BIOLOGICAL RESEARCH","description":"","frontmatter":{"legisId":"2025-05-05-improving-the-safety-and-security-of-biological-research","title":"IMPROVING THE SAFETY AND SECURITY OF BIOLOGICAL RESEARCH","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/05/improving-the-safety-and-security-of-biological-research/","publishDate":"2025-05-05T17:59:15-04:00"},"headers":[],"relativePath":"executive-orders/2025-05-05-improving-the-safety-and-security-of-biological-research.md","filePath":"executive-orders/2025-05-05-improving-the-safety-and-security-of-biological-research.md"}'),c={name:"executive-orders/2025-05-05-improving-the-safety-and-security-of-biological-research.md"},g=Object.assign(c,{setup(l){return(d,e)=>(n(),t("div",null,[e[0]||(e[0]=i("h1",{id:"improving-the-safety-and-security-of-biological-research",tabindex:"-1"},[s("IMPROVING THE SAFETY AND SECURITY OF BIOLOGICAL RESEARCH "),i("a",{class:"header-anchor",href:"#improving-the-safety-and-security-of-biological-research","aria-label":'Permalink to "IMPROVING THE SAFETY AND SECURITY OF BIOLOGICAL RESEARCH"'},"​")],-1)),r(a),e[1]||(e[1]=o('<p>Published on Monday, May 5, 2025</p><ul><li>The executive order addresses concerns regarding dangerous gain-of-function research on biological agents and pathogens.</li><li>It emphasizes that such research poses significant risks to American citizens, including potential widespread mortality, impaired public health, and threats to national security.</li><li>The Biden Administration&#39;s previous approach allowed dangerous gain-of-function research with insufficient oversight and authorized life-science funding in foreign countries with limited U.S. oversight.</li><li>The order prioritizes U.S. federally funded research benefiting citizens without compromising national security, public health, or economic stability.</li><li>Key directives include: <ul><li>Immediate cessation of federal funding for dangerous gain-of-function research abroad, particularly in countries of concern (like China).</li><li>Suspension of federally funded dangerous gain-of-function research until new policy guidance is developed.</li></ul></li><li>The Office of Science and Technology Policy (OSTP) must revise existing guidelines to: <ul><li>Enhance oversight, accountability, transparency, and define research scope while maintaining U.S. leadership in health research.</li><li>Incorporate enforcement mechanisms in federal funding agreements.</li></ul></li><li>Within specified timelines, further actions must be taken to limit and track dangerous gain-of-function research, even outside federal funding.</li><li>Institutions receiving federal funding must report on their gain-of-function research activities and comply with new contractual requirements.</li><li>“Dangerous gain-of-function research” is defined broadly to encompass activities that enhance infectious agents&#39; harmfulness or transmissibility and could lead to significant societal consequences.</li><li>Clauses specify that the order does not infringe on existing legal authorities of departments and agencies.</li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/05/improving-the-safety-and-security-of-biological-research/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/05/improving-the-safety-and-security-of-biological-research/</a></p>',3))]))}});export{f as __pageData,g as default};
